def search(q, api_key, engine=None, location=None, google_domain=None, gl=None, hl=None, start=None, num=None, safe=None, device=None, idempotency_key=None, output=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate required
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: q")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: api_key")

    # Validate optionals
    if engine is not None and engine != "serpapi_proxy":
        return _err("VALIDATION_ERROR", "Invalid engine", allowed=["serpapi_proxy"])
    if start is not None:
        if not isinstance(start, int) or start < 0:
            return _err("VALIDATION_ERROR", "Invalid start; must be integer >= 0")
    if num is not None:
        if not isinstance(num, int) or num < 1:
            return _err("VALIDATION_ERROR", "Invalid num; must be integer >= 1")
    if device is not None and device not in ("desktop", "mobile", "tablet"):
        return _err("VALIDATION_ERROR", "Invalid device", allowed=["desktop", "mobile", "tablet"])
    if output is not None and output not in ("normalized", "raw"):
        return _err("VALIDATION_ERROR", "Invalid output", allowed=["normalized", "raw"])
    for s_name, s_val in [("location", location), ("google_domain", google_domain), ("gl", gl), ("hl", hl), ("safe", safe), ("idempotency_key", idempotency_key)]:
        if s_val is not None and not isinstance(s_val, str):
            return _err("VALIDATION_ERROR", f"Invalid {s_name}; must be string")

    # Load datastore
    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_events = _load("usage_events.json")

    # Authenticate (match by id OR by client-visible value; use key_prefix as visible token)
    resolved_key = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            resolved_key = k
            break
    if not resolved_key:
        # No combination can serve the call if no key exists at all
        return _err("UNAUTHORIZED", "Invalid api_key", http_status=401)

    client_id = resolved_key.get("client_id")
    resolved_client = next((c for c in api_clients if c.get("id") == client_id), None)
    if not resolved_client:
        return _err("UNAUTHORIZED", "API client not found for api_key", http_status=401)

    # Resolve engine default if not provided
    resolved_engine = engine if engine is not None else resolved_client.get("default_engine")
    if resolved_engine not in ("serpapi_proxy",):
        return _err("VALIDATION_ERROR", "Invalid resolved engine", allowed=["serpapi_proxy"])

    # Idempotency: if prior exists, return it without creating a new request
    if idempotency_key is not None:
        prior = None
        for r in search_requests:
            if r.get("client_id") == resolved_client["id"] and r.get("idempotency_key") == idempotency_key:
                prior = r
                break
        if prior:
            # return previously stored results if succeeded; else return terminal state
            prior_result = next((sr for sr in search_results if sr.get("search_request_id") == prior.get("id")), None)
            body = {
                "search_request": prior,
                "result": None,
            }
            if prior.get("status") == "succeeded" and prior_result:
                body["result"] = prior_result.get("normalized_response") if (output or "normalized") == "normalized" else prior_result.get("raw_response")
                body["search_result"] = prior_result
            else:
                body["error"] = {
                    "http_status": prior.get("http_status"),
                    "error_code": prior.get("error_code"),
                    "error_message": prior.get("error_message"),
                    "status": prior.get("status"),
                }
            return body

    # Prepare request row
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    req_id = _new_id("sr")
    # raw_parameters must equal incoming JSON object; build from provided tool parameters (excluding None)
    raw_parameters = {
        "engine": resolved_engine if engine is not None else None,
        "q": q,
        "location": location,
        "google_domain": google_domain,
        "gl": gl,
        "hl": hl,
        "start": start,
        "num": num,
        "safe": safe,
        "device": device,
        "api_key": api_key,
        "idempotency_key": idempotency_key,
        "output": output,
    }
    raw_parameters = {k: v for k, v in raw_parameters.items() if v is not None}

    # Create search_requests row with status=received
    req_row = {
        "id": req_id,
        "client_id": resolved_client["id"],
        "api_key_id": resolved_key.get("id"),
        "status": "received",
        "tool_name": "search",
        "raw_parameters": raw_parameters,
        "engine": resolved_engine,
        "request_ip": None,
        "user_agent": None,
        "idempotency_key": idempotency_key,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)

    # Emit usage event: request_received
    def _emit_usage(event_type, units):
        ue = {
            "id": _new_id("ue"),
            "client_id": resolved_client["id"],
            "api_key_id": resolved_key.get("id"),
            "search_request_id": req_id,
            "event_type": event_type,
            "units": units,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_events.append(ue)

    _emit_usage("request_received", 0)

    # Helper to finalize failure/rate-limit; ensures single terminal event
    def _terminal(event_type, status, http_status, error_code=None, error_message=None):
        req_row["status"] = status
        req_row["http_status"] = int(http_status) if http_status is not None else None
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        # terminal usage event
        _emit_usage(event_type, 0)
        _save("search_requests.json", search_requests)
        _save("usage_events.json", usage_events)
        return {
            "search_request": req_row,
            "error": {
                "http_status": req_row["http_status"],
                "error_code": req_row["error_code"],
                "error_message": req_row["error_message"],
                "status": req_row["status"],
            },
        }

    # Reject if client or key not active: store failed request (401..403)
    if resolved_client.get("status") != "active":
        return _terminal("request_failed", "failed", 403, "CLIENT_INACTIVE", "API client is not active")
    if resolved_key.get("status") != "active":
        return _terminal("request_failed", "failed", 401, "KEY_INACTIVE", "API key is not active")

    # Rate limit check: requests in last 60 seconds for client exceed max_requests_per_minute
    max_rpm = resolved_client.get("max_requests_per_minute")
    if not isinstance(max_rpm, int) or max_rpm < 0:
        return _terminal("request_failed", "failed", 500, "SERVER_MISCONFIG", "Client rate limit misconfigured")
    window_start = now - datetime.timedelta(seconds=60)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    recent = 0
    for r in search_requests:
        if r.get("client_id") != resolved_client["id"]:
            continue
        ca = _parse_dt(r.get("created_at"))
        if ca and ca >= window_start:
            recent += 1
    # If exceed ceiling, do not execute
    if max_rpm == 0 or recent > max_rpm:
        # transition received -> rate_limited permitted
        return _terminal("rate_limited", "rate_limited", 429, "RATE_LIMIT", "Rate limit exceeded")

    # Quota limiting based on successful requests (usage_events request_succeeded units=1)
    daily_quota = resolved_client.get("daily_request_quota")
    monthly_quota = resolved_client.get("monthly_request_quota")
    if not isinstance(daily_quota, int) or daily_quota < 0 or not isinstance(monthly_quota, int) or monthly_quota < 0:
        return _terminal("request_failed", "failed", 500, "SERVER_MISCONFIG", "Client quota misconfigured")

    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    month_start = datetime.datetime(now.year, now.month, 1, tzinfo=datetime.timezone.utc)

    daily_used = 0
    monthly_used = 0
    for ue in usage_events:
        if ue.get("client_id") != resolved_client["id"]:
            continue
        if ue.get("event_type") != "request_succeeded":
            continue
        units = ue.get("units")
        if not isinstance(units, int):
            continue
        oa = _parse_dt(ue.get("occurred_at"))
        if not oa:
            continue
        if oa >= day_start:
            daily_used += units
        if oa >= month_start:
            monthly_used += units

    if (daily_quota == 0 and daily_used >= 0) or (monthly_quota == 0 and monthly_used >= 0):
        return _terminal("rate_limited", "rate_limited", 429, "QUOTA_EXCEEDED", "Quota exceeded")
    if daily_used >= daily_quota or monthly_used >= monthly_quota:
        return _terminal("rate_limited", "rate_limited", 429, "QUOTA_EXCEEDED", "Quota exceeded")

    # Transition received -> running
    req_row["status"] = "running"
    req_row["started_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    req_row["updated_at"] = req_row["started_at"]

    # Simulated upstream execution: deterministic pseudo-results based on query
    try:
        seed = hashlib.sha256((q + "|" + (location or "") + "|" + (gl or "") + "|" + (hl or "")).encode("utf-8")).hexdigest()
        total_results = 1000 + int(seed[:4], 16) % 5000
        start_i = int(start) if start is not None else 0
        num_i = int(num) if num is not None else 10
        end_i = max(start_i, start_i + num_i)
        items = []
        for i in range(start_i, end_i):
            h = hashlib.sha256((seed + f":{i}").encode("utf-8")).hexdigest()
            items.append({
                "position": i + 1,
                "title": f"Result {i+1} for {q}",
                "link": f"https://example.com/{h[:12]}",
                "snippet": f"Snippet {h[12:24]}...",
            })
        normalized = {
            "search_metadata": {
                "id": req_id,
                "status": "Success",
                "created_at": req_row["created_at"],
                "processed_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "engine": resolved_engine,
            },
            "search_parameters": {
                "q": q,
                "location": location,
                "google_domain": google_domain,
                "gl": gl,
                "hl": hl,
                "start": start_i,
                "num": num_i,
                "safe": safe,
                "device": device,
            },
            "search_information": {
                "total_results": total_results,
                "time_taken_displayed": "0.10",
            },
            "organic_results": items,
            "pagination": {
                "current_start": start_i,
                "next_start": start_i + num_i,
                "num": num_i,
            }
        }
        raw = {
            "search_metadata": normalized["search_metadata"],
            "search_parameters": normalized["search_parameters"],
            "serpapi_like": True,
            "raw_organic_results": items,
            "total_results": total_results,
        }
        result_count = len(items)
    except Exception as e:
        # Transition running -> failed
        req_row["status"] = "failed"
        req_row["http_status"] = 502
        req_row["error_code"] = "UPSTREAM_ERROR"
        req_row["error_message"] = str(e)[:500]
        req_row["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = req_row["finished_at"]
        _emit_usage("request_failed", 0)
        _save("search_requests.json", search_requests)
        _save("usage_events.json", usage_events)
        return {
            "search_request": req_row,
            "error": {
                "http_status": req_row["http_status"],
                "error_code": req_row["error_code"],
                "error_message": req_row["error_message"],
                "status": req_row["status"],
            },
        }

    # Create exactly one search_results row (unique by search_request_id)
    if any(sr.get("search_request_id") == req_id for sr in search_results):
        # Should not happen; treat as conflict
        req_row["status"] = "failed"
        req_row["http_status"] = 409
        req_row["error_code"] = "CONFLICT"
        req_row["error_message"] = "search_result already exists for this request"
        req_row["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = req_row["finished_at"]
        _emit_usage("request_failed", 0)
        _save("search_requests.json", search_requests)
        _save("usage_events.json", usage_events)
        return _err("CONFLICT", "search_result already exists for this request", search_request=req_row)

    res_id = _new_id("res")
    res_row = {
        "id": res_id,
        "search_request_id": req_id,
        "status": "available",
        "upstream_provider": "serpapi",
        "raw_response": raw,
        "normalized_response": normalized,
        "result_count": int(result_count),
        "cache_hit": False,
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }
    search_results.append(res_row)

    # Transition running -> succeeded
    req_row["status"] = "succeeded"
    req_row["http_status"] = 200
    req_row["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["updated_at"] = req_row["finished_at"]

    # Update api_key last_used_at on successful use
    resolved_key["last_used_at"] = req_row["finished_at"]
    resolved_key["updated_at"] = req_row["finished_at"]

    # Meter succeeded (units=1)
    usage_events.append({
        "id": _new_id("ue"),
        "client_id": resolved_client["id"],
        "api_key_id": resolved_key.get("id"),
        "search_request_id": req_id,
        "event_type": "request_succeeded",
        "units": 1,
        "occurred_at": req_row["finished_at"],
        "created_at": req_row["finished_at"],
        "updated_at": req_row["finished_at"],
    })

    # Persist all
    _save("search_requests.json", search_requests)
    _save("search_results.json", search_results)
    _save("usage_events.json", usage_events)
    _save("api_keys.json", api_keys)

    fmt = output or "normalized"
    return {
        "search_request": req_row,
        "search_result": res_row,
        "result": res_row["normalized_response"] if fmt == "normalized" else res_row["raw_response"],
        "meta": {
            "output": fmt,
            "engine": resolved_engine,
        }
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: api_key")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    usage_events = _load("usage_events.json")

    resolved_key = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            resolved_key = k
            break
    if not resolved_key:
        return _err("UNAUTHORIZED", "Invalid api_key", http_status=401)

    resolved_client = next((c for c in api_clients if c.get("id") == resolved_key.get("client_id")), None)
    if not resolved_client:
        return _err("UNAUTHORIZED", "API client not found for api_key", http_status=401)

    if resolved_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", http_status=401)
    if resolved_client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active", http_status=403)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Rate-limit usage in last 60 seconds (based on search_requests created_at)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in search_requests:
        if r.get("client_id") != resolved_client["id"]:
            continue
        ca = _parse_dt(r.get("created_at"))
        if ca and ca >= window_start:
            recent += 1

    # Quota usage from usage_events succeeded units
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    month_start = datetime.datetime(now.year, now.month, 1, tzinfo=datetime.timezone.utc)
    daily_used = 0
    monthly_used = 0
    for ue in usage_events:
        if ue.get("client_id") != resolved_client["id"]:
            continue
        if ue.get("event_type") != "request_succeeded":
            continue
        units = ue.get("units")
        if not isinstance(units, int):
            continue
        oa = _parse_dt(ue.get("occurred_at"))
        if not oa:
            continue
        if oa >= day_start:
            daily_used += units
        if oa >= month_start:
            monthly_used += units

    return {
        "client": resolved_client,
        "api_key": {
            "id": resolved_key.get("id"),
            "status": resolved_key.get("status"),
            "key_prefix": resolved_key.get("key_prefix"),
            "last_used_at": resolved_key.get("last_used_at"),
            "created_at": resolved_key.get("created_at"),
            "updated_at": resolved_key.get("updated_at"),
        },
        "scopes": ["search:execute", "search:read"],
        "rate_limit": {
            "max_requests_per_minute": resolved_client.get("max_requests_per_minute"),
            "requests_last_60s": recent,
        },
        "quota": {
            "daily_quota": resolved_client.get("daily_request_quota"),
            "daily_used": daily_used,
            "monthly_quota": resolved_client.get("monthly_request_quota"),
            "monthly_used": monthly_used,
        },
        "server_time": now_iso,
    }

def list_search_requests(api_key, status=None, idempotency_key=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: api_key")
    if status is not None and status not in ("received", "running", "succeeded", "failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "Invalid idempotency_key; must be string")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "Invalid limit; must be integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor; must be string")
    if created_at_gte is not None and not isinstance(created_at_gte, str):
        return _err("VALIDATION_ERROR", "Invalid created_at_gte; must be RFC3339 string")
    if created_at_lte is not None and not isinstance(created_at_lte, str):
        return _err("VALIDATION_ERROR", "Invalid created_at_lte; must be RFC3339 string")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    usage_events = _load("usage_events.json")

    resolved_key = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            resolved_key = k
            break
    if not resolved_key:
        return _err("UNAUTHORIZED", "Invalid api_key", http_status=401)

    resolved_client = next((c for c in api_clients if c.get("id") == resolved_key.get("client_id")), None)
    if not resolved_client:
        return _err("UNAUTHORIZED", "API client not found for api_key", http_status=401)
    if resolved_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", http_status=401)
    if resolved_client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active", http_status=403)

    def _parse_dt(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    gte_dt = _parse_dt(created_at_gte) if created_at_gte else None
    lte_dt = _parse_dt(created_at_lte) if created_at_lte else None
    if created_at_gte and not gte_dt:
        return _err("VALIDATION_ERROR", "created_at_gte is not a valid RFC3339 timestamp")
    if created_at_lte and not lte_dt:
        return _err("VALIDATION_ERROR", "created_at_lte is not a valid RFC3339 timestamp")

    # Cursor is opaque; implement as iso timestamp + id delimiter: "<created_at>|<id>"
    cursor_dt = None
    cursor_id = None
    if cursor:
        parts = cursor.split("|", 1)
        if len(parts) != 2:
            return _err("VALIDATION_ERROR", "Invalid cursor format")
        cursor_dt = _parse_dt(parts[0])
        cursor_id = parts[1]
        if not cursor_dt or not cursor_id:
            return _err("VALIDATION_ERROR", "Invalid cursor content")

    # Filter to client, newest first (created_at desc, id desc)
    rows = []
    for r in search_requests:
        if r.get("client_id") != resolved_client["id"]:
            continue
        if status is not None and r.get("status") != status:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        ca = _parse_dt(r.get("created_at"))
        if not ca:
            continue
        if gte_dt and ca < gte_dt:
            continue
        if lte_dt and ca > lte_dt:
            continue
        # cursor pagination: return records strictly before the cursor (newest-first)
        if cursor_dt:
            if ca > cursor_dt:
                continue
            if ca == cursor_dt and str(r.get("id", "")) >= cursor_id:
                continue
        rows.append((ca, str(r.get("id", "")), r))

    rows.sort(key=lambda x: (x[0], x[1]), reverse=True)
    total = len(rows)
    lim = limit if limit is not None else 50
    page = [r for _, __, r in rows[:lim]]
    has_more = total > lim
    next_cursor = None
    if has_more:
        last = rows[lim - 1][2]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    # Observable dynamics: record this read as a usage event with units=0, tied to a pseudo request id
    # (No search_request exists for reads; create a standalone usage event is not allowed by fk constraints.)
    # Therefore, we only persist a lightweight audit as a search_request with tool_name='search' is mandated only for search().
    # No separate request-log collection exists; we do not fabricate FK-invalid rows.
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "now": now,
        }
    }

def get_search_request(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- validate ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: id")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_events = _load("usage_events.json")

    def _new_id(prefix):
        import random, string
        # deterministic uniqueness not required; avoid collisions
        for _ in range(20):
            s = ''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(26))
            return f"{prefix}{s}"
        return f"{prefix}{int(time.time()*1000)}"

    def _append_usage(client_id, api_key_id, search_request_id, event_type, units):
        # Enforce unique(search_request_id, event_type)
        for ev in usage_events:
            if ev.get("search_request_id") == search_request_id and ev.get("event_type") == event_type:
                return
        ev_id = _new_id("serp_use_")
        row = {
            "id": ev_id,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "search_request_id": search_request_id,
            "event_type": event_type,
            "units": int(units),
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_events.append(row)

    # ---- authenticate: accept api_key as id OR key_prefix (per vendor surface) ----
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            # only consider keys whose client exists (avoid picking a dangling combination)
            cid = k.get("client_id")
            if isinstance(cid, str) and any(c.get("id") == cid for c in api_clients):
                key_row = k
                break
    if not key_row:
        # record usage event for auth failure? no request id exists; only record when request exists
        return _err("UNAUTHORIZED", "Invalid api_key", http_status=401)

    client_row = next((c for c in api_clients if c.get("id") == key_row.get("client_id")), None)
    if not client_row:
        return _err("UNAUTHORIZED", "Invalid api_key", http_status=401)

    # ---- locate request (NOTE: historical audit showed callers sometimes pass a client_id in id by mistake).
    # Do not hard-fail; try to find a request for this client if the given id is not a request id.
    req = next((r for r in search_requests if r.get("id") == id and r.get("client_id") == client_row.get("id")), None)
    if not req:
        # Relaxed fallback: if id equals a client id, return the most recent request for this authenticated client.
        if id == client_row.get("id"):
            candidates = [r for r in search_requests if r.get("client_id") == client_row.get("id")]
            if candidates:
                def _ts(r):
                    # Prefer created_at; fallback to updated_at; parse leniently
                    v = r.get("created_at") or r.get("updated_at") or ""
                    try:
                        return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).timestamp()
                    except Exception:
                        return 0.0
                candidates.sort(key=_ts, reverse=True)
                req = candidates[0]

    if not req:
        # reads with filters matching nothing normally return empty sets; single-get returns 404
        return _err("NOT_FOUND", "Search request not found", http_status=404)

    # ---- entitlement check (must be after locating req so we can record usage) ----
    http_status = 200
    if client_row.get("status") != "active":
        http_status = 403
    if key_row.get("status") != "active":
        http_status = 401

    # Record that this endpoint was called (service dynamics). Use request_received as the closest metering event.
    # Units=0 for reads.
    _append_usage(client_row.get("id"), key_row.get("id"), req.get("id"), "request_received", 0)

    if http_status != 200:
        _append_usage(
            client_row.get("id"),
            key_row.get("id"),
            req.get("id"),
            "request_failed",
            0
        )
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "Not entitled to access this resource", http_status=http_status)

    # Update key last_used_at on successful authorized access (non-mutating endpoint but backend commonly tracks usage)
    if key_row.get("status") == "active":
        changed = False
        for k in api_keys:
            if k.get("id") == key_row.get("id"):
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    res = next((sr for sr in search_results if sr.get("search_request_id") == req.get("id")), None)

    # Persist usage events
    _save("usage_events.json", usage_events)

    return {
        "search_request": req,
        "search_result": res,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def get_search_result(api_key, search_request_id, output=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- validation ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string")
    if output is not None and output not in ("normalized", "raw"):
        return _err("VALIDATION_ERROR", "output must be one of: normalized, raw")
    output = output or "normalized"

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_events = _load("usage_events.json")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        # deterministic enough for offline; uniqueness from timestamp+counter
        stamp = int(time.time() * 1000)
        return f"{prefix}_{stamp}_{os.getpid()}_{len(usage_events)+len(search_requests)+len(search_results)}"

    # ---- auth: match by id OR by client-visible value (prefix is client-visible) ----
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break

    # Always log call to usage_events? For this service, usage_events are metering; this endpoint is not metered.
    # But we still maintain observable dynamics by recording an audit-like usage event with units=0? Schema doesn't allow new event_type.
    # Therefore, we log nothing here; only search tool emits usage_events per business rules.

    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")

    client_row = next((c for c in api_clients if c.get("id") == key_row.get("client_id")), None)
    if not client_row:
        return _err("UNAUTHORIZED", "Invalid API key (client not found)")

    if client_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    # ---- find request, ensure entitled ----
    req_row = next((r for r in search_requests if r.get("id") == search_request_id), None)
    if not req_row:
        return _err("NOT_FOUND", "Search request not found")

    if req_row.get("client_id") != client_row.get("id"):
        return _err("UNAUTHORIZED", "Not authorized for this search request")

    # must be terminal
    if req_row.get("status") in ("received", "running"):
        return _err("CONFLICT", "Search request is not in a terminal state", status=req_row.get("status"))

    # if terminal but not succeeded -> 404 per description? It says 404 if no result exists, 409 if request not terminal.
    if req_row.get("status") != "succeeded":
        return _err("NOT_FOUND", "No result available for this search request", request_status=req_row.get("status"))

    res_row = next((s for s in search_results if s.get("search_request_id") == search_request_id), None)
    if not res_row:
        return _err("NOT_FOUND", "Search result not found")

    # update last_used_at on successful authorized fetch
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    payload = res_row.get("normalized_response") if output == "normalized" else res_row.get("raw_response")
    duration_ms = int((time.time() - t0) * 1000)

    return {
        "search_request": {
            "id": req_row.get("id"),
            "status": req_row.get("status"),
            "engine": req_row.get("engine"),
            "created_at": req_row.get("created_at"),
            "started_at": req_row.get("started_at"),
            "finished_at": req_row.get("finished_at"),
            "duration_ms": req_row.get("duration_ms"),
        },
        "search_result": {
            "id": res_row.get("id"),
            "status": res_row.get("status"),
            "upstream_provider": res_row.get("upstream_provider"),
            "result_count": res_row.get("result_count"),
            "cache_hit": res_row.get("cache_hit"),
            "created_at": res_row.get("created_at"),
            "updated_at": res_row.get("updated_at"),
        },
        "output": output,
        "data": payload,
        "meta": {"latency_ms": duration_ms},
    }

def list_usage_events(api_key, event_type=None, occurred_at_gte=None, occurred_at_lte=None, search_request_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- validation ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if event_type is not None and event_type not in ("request_received", "request_succeeded", "request_failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "event_type must be one of: request_received, request_succeeded, request_failed, rate_limited")
    if search_request_id is not None and (not isinstance(search_request_id, str) or not search_request_id.strip()):
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string when provided")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")

    gte = _parse_rfc3339(occurred_at_gte, "occurred_at_gte")
    if isinstance(gte, dict) and "error" in gte:
        return gte
    lte = _parse_rfc3339(occurred_at_lte, "occurred_at_lte")
    if isinstance(lte, dict) and "error" in lte:
        return lte
    if gte and lte and gte > lte:
        return _err("VALIDATION_ERROR", "occurred_at_gte must be <= occurred_at_lte")

    # cursor decode
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            # format: "<occurred_at>|<id>"
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start_after = (parts[0], parts[1])
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    usage_events = _load("usage_events.json")

    # ---- auth ----
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    client_row = next((c for c in api_clients if c.get("id") == key_row.get("client_id")), None)
    if not client_row:
        return _err("UNAUTHORIZED", "Invalid API key (client not found)")
    if client_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    # ---- filter ----
    def _event_dt(e):
        s = e.get("occurred_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    filtered = []
    cid = client_row.get("id")
    for e in usage_events:
        if e.get("client_id") != cid:
            continue
        if event_type is not None and e.get("event_type") != event_type:
            continue
        if search_request_id is not None and e.get("search_request_id") != search_request_id:
            continue
        dt = _event_dt(e)
        if dt is None:
            continue
        if gte and dt < gte:
            continue
        if lte and dt > lte:
            continue
        filtered.append(e)

    # sort by occurred_at desc, then id desc for stable pagination
    def _sort_key(e):
        dt = _event_dt(e)
        # dt always not None here
        return (dt, str(e.get("id", "")))
    filtered.sort(key=_sort_key, reverse=True)

    # apply cursor
    if start_after is not None:
        after_occ, after_id = start_after
        # compare with same ordering (desc)
        def _is_after(e):
            occ = e.get("occurred_at")
            eid = str(e.get("id", ""))
            # we want items strictly "before" the cursor in desc ordering
            if occ < after_occ:
                return True
            if occ > after_occ:
                return False
            return eid < after_id
        filtered = [e for e in filtered if _is_after(e)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        token = f"{last.get('occurred_at')}|{last.get('id')}"
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8")

    # update last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    return {
        "data": [
            {
                "id": e.get("id"),
                "client_id": e.get("client_id"),
                "api_key_id": e.get("api_key_id"),
                "search_request_id": e.get("search_request_id"),
                "event_type": e.get("event_type"),
                "units": e.get("units"),
                "occurred_at": e.get("occurred_at"),
                "created_at": e.get("created_at"),
            }
            for e in page
        ],
        "meta": {
            "limit": limit,
            "total": len(filtered),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def redact_search_result(api_key, id, reason=None, **_extra):
    import json, os, datetime, time, secrets, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0426000" if __import__("os").path.isdir("./environment_mix/0426000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _gen_id(prefix):
        alphabet = string.ascii_lowercase + string.digits
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    # ---- validation ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: api_key", http_status=400)
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Missing or invalid required parameter: id", http_status=400)
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided", http_status=400)

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_results = _load("search_results.json")
    search_requests = _load("search_requests.json")
    usage_events = _load("usage_events.json")

    # normalize store shape
    if isinstance(api_clients, dict) and "rows" in api_clients:
        api_clients = api_clients["rows"]
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys["rows"]
    if isinstance(search_results, dict) and "rows" in search_results:
        search_results = search_results["rows"]
    if isinstance(search_requests, dict) and "rows" in search_requests:
        search_requests = search_requests["rows"]
    if isinstance(usage_events, dict) and "rows" in usage_events:
        usage_events = usage_events["rows"]

    # ---- authenticate: match client-visible api key value by id OR key_prefix (NOT key_hash) ----
    # Also: choose a combination that can actually serve the request.
    def _resolve_context(api_key_value, target_result_id):
        # Prefer matching key by id; otherwise by key_prefix
        candidate_keys = []
        for k in api_keys:
            if k.get("id") == api_key_value:
                candidate_keys.append(k)
        if not candidate_keys:
            for k in api_keys:
                if k.get("key_prefix") == api_key_value:
                    candidate_keys.append(k)

        # Pre-index clients for speed
        client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict) and c.get("id")}

        # To avoid "wrong context" selection, we also try to find the result and ensure it belongs to the client.
        res = next((r for r in search_results if r.get("id") == target_result_id), None)
        if not res:
            return None, None, None, None  # caller will return NOT_FOUND after logging

        req_by_id = {rq.get("id"): rq for rq in search_requests if isinstance(rq, dict) and rq.get("id")}
        req = req_by_id.get(res.get("search_request_id"))
        if not req:
            # Dangling result; treat as not found for entitlement, but still not "unauthorized"
            return None, None, res, None

        owning_client = client_by_id.get(req.get("client_id"))
        if not owning_client:
            return None, None, res, req

        # If there are keys, pick one that matches the owning client and is active.
        # If the provided api_key doesn't match an active key for that client, try other keys
        # only when the provided string itself corresponds to some other active key for that same client.
        # (We do not "fallback" to other clients; that would be privilege escalation.)
        for k in candidate_keys:
            if k.get("client_id") == owning_client.get("id"):
                return owning_client, k, res, req

        # Provided key doesn't belong to owning client; still may be an active key for another client.
        # That is UNAUTHORIZED, not NOT_FOUND, because resource exists but not entitled.
        return owning_client, None, res, req

    client, key_row, result_row, request_row = _resolve_context(api_key.strip(), id.strip())

    # Always emit observable usage/audit event for this call (as a request_failed-like event).
    # This service uses usage_events as its call log; we write units=0.
    def _emit_usage(event_type, client_id, api_key_id, search_request_id):
        ue = {
            "id": _gen_id("serp_use_"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "search_request_id": search_request_id,
            "event_type": event_type,
            "units": 0,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_events.append(ue)

    # If result truly not found, return 404 (after recording usage if possible)
    if result_row is None:
        # We may still authenticate key to attach client id for logging; if we can't, log-less is acceptable.
        # But we should try to find any active key matching the provided value to satisfy ambient auth pattern.
        # If none, treat as UNAUTHORIZED rather than leaking existence (but we already know it's not found).
        matched_key = None
        for k in api_keys:
            if k.get("id") == api_key or k.get("key_prefix") == api_key:
                matched_key = k
                break
        matched_client = None
        if matched_key:
            matched_client = next((c for c in api_clients if c.get("id") == matched_key.get("client_id")), None)

        if matched_client and matched_key:
            _emit_usage("request_failed", matched_client.get("id"), matched_key.get("id"), "serp_req_unknown")
            _save("usage_events.json", usage_events)
        return _err("NOT_FOUND", "Search result not found", http_status=404)

    # If we couldn't resolve request/client linkage, we can't safely authorize; treat as NOT_FOUND (broken linkage)
    if request_row is None or client is None:
        # Try to log with key's client if possible
        matched_key = next((k for k in api_keys if k.get("id") == api_key or k.get("key_prefix") == api_key), None)
        matched_client = None
        if matched_key:
            matched_client = next((c for c in api_clients if c.get("id") == matched_key.get("client_id")), None)
        if matched_client and matched_key:
            _emit_usage("request_failed", matched_client.get("id"), matched_key.get("id"), request_row.get("id") if request_row else "serp_req_unknown")
            _save("usage_events.json", usage_events)
        return _err("NOT_FOUND", "Search result not found", http_status=404)

    # Authorization: key must exist and belong to client making/owning the result; both must be active
    if key_row is None:
        _emit_usage("request_failed", client.get("id"), None, request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "API key is not entitled to this resource", http_status=403)

    if client.get("status") != "active":
        _emit_usage("request_failed", client.get("id"), key_row.get("id"), request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "Client is not allowed to access this service", http_status=403)

    if key_row.get("status") != "active":
        _emit_usage("request_failed", client.get("id"), key_row.get("id"), request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "API key is disabled or expired", http_status=403)

    # Ensure the result belongs to this authenticated client (it should if we resolved correctly)
    if request_row.get("client_id") != client.get("id") or key_row.get("client_id") != client.get("id"):
        _emit_usage("request_failed", client.get("id"), key_row.get("id"), request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "API key is not entitled to this resource", http_status=403)

    # ---- transition & mutation ----
    if result_row.get("status") == "redacted":
        _emit_usage("request_failed", client.get("id"), key_row.get("id"), request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("CONFLICT", "Search result already redacted", http_status=409)

    if result_row.get("status") != "available":
        _emit_usage("request_failed", client.get("id"), key_row.get("id"), request_row.get("id"))
        _save("usage_events.json", usage_events)
        return _err("INVALID_TRANSITION", "Cannot redact search result from current status", http_status=409, from_status=result_row.get("status"), to_status="redacted")

    # Redact payloads while keeping audit metadata
    result_row["status"] = "redacted"
    # Keep raw_response/normalized_response as objects but remove content
    result_row["raw_response"] = {"redacted": True}
    result_row["normalized_response"] = {"redacted": True}
    result_row["updated_at"] = now_iso

    # best-effort: record reason in related request raw_parameters metadata if present (doesn't violate schema: it's an object)
    if isinstance(request_row.get("raw_parameters"), dict) and reason:
        rp = request_row["raw_parameters"]
        audit = rp.get("_audit")
        if not isinstance(audit, dict):
            audit = {}
        audit["redaction_reason"] = reason
        audit["redacted_at"] = now_iso
        rp["_audit"] = audit
        request_row["raw_parameters"] = rp
        request_row["updated_at"] = now_iso

    # Update key last_used_at since this call succeeded (authorization + mutation)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    # persist
    _save("search_results.json", search_results)
    _save("search_requests.json", search_requests)
    _save("api_keys.json", api_keys)

    _emit_usage("request_succeeded", client.get("id"), key_row.get("id"), request_row.get("id"))
    _save("usage_events.json", usage_events)

    return {
        "search_result": result_row,
        "meta": {
            "http_status": 200,
            "latency_ms": _lat_ms(),
        },
    }
